import * as THREE from 'three';
import { gsap } from 'gsap';

/**
 * Precision hero centrepiece: a CAD-style wireframe coffee bean.
 * - Latitude / longitude lines are generated by hand (not WireframeGeometry) so the grid reads as
 *   measured quads, and the crease shows up as a notch where each ring crosses it.
 * - A solid occluder in the page ground colour hides back-facing lines (hidden-line removal).
 * - Pointer parallax + scroll-scrubbed rotation. One static frame under reduced motion.
 */
export function mountBean(canvas: HTMLCanvasElement, hero: HTMLElement, reduced: boolean) {
  let renderer: THREE.WebGLRenderer;
  try {
    renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'low-power' });
  } catch {
    return null; // no WebGL: the CSS rings stay visible
  }
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setClearColor(0x000000, 0);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 50);
  camera.position.set(0, 0, 7.4);

  // ---- the bean surface: unit sphere with its pole on x, flattened, creased on +z ----
  const creaseY = (X: number) => 0.1 * Math.sin(X * 2.2);
  const deform = (x: number, y: number, z: number, out = new THREE.Vector3()) => {
    const X = x * 1.5;
    let Y = y * 0.98;
    let Z = z * (z > 0 ? 0.7 : 0.9); // flatter face, domed back
    if (Z > 0) {
      const centre = creaseY(X); // the crease wanders in a gentle S
      const d = Y - centre;
      const taper = THREE.MathUtils.smoothstep(1.3 - Math.abs(X), 0, 0.55); // fades out toward the ends
      const g = Math.exp(-(d * d) / (2 * 0.1 * 0.1));
      const k = g * taper * Math.min(1, Z / 0.3);
      Z -= 0.26 * k; // dip in depth (reads in profile)...
      Y -= d * 0.42 * k; // ...and pinch lines toward the centre (reads head-on)
    }
    return out.set(X, Y, Z);
  };
  const onSphere = (theta: number, phi: number) =>
    deform(Math.cos(theta), Math.sin(theta) * Math.cos(phi), Math.sin(theta) * Math.sin(phi));

  const RINGS = 30, SAMPLES = 120, MERIDIANS = 72, STEPS = 80;
  const verts: number[] = [];
  const seg = (a: THREE.Vector3, b: THREE.Vector3) => verts.push(a.x, a.y, a.z, b.x, b.y, b.z);
  for (let k = 1; k < RINGS; k++) {
    const theta = (k / RINGS) * Math.PI;
    let prev = onSphere(theta, 0).clone();
    for (let s = 1; s <= SAMPLES; s++) {
      const cur = onSphere(theta, (s / SAMPLES) * Math.PI * 2).clone();
      seg(prev, cur);
      prev = cur;
    }
  }
  for (let m = 0; m < MERIDIANS; m++) {
    const phi = (m / MERIDIANS) * Math.PI * 2;
    let prev = onSphere(0, phi).clone();
    for (let n = 1; n <= STEPS; n++) {
      const cur = onSphere((n / STEPS) * Math.PI, phi).clone();
      seg(prev, cur);
      prev = cur;
    }
  }
  const lineGeo = new THREE.BufferGeometry();
  lineGeo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  const lineMat = new THREE.LineBasicMaterial({ color: 0xd8d8d8, transparent: true, opacity: 0.5 });
  const lines = new THREE.LineSegments(lineGeo, lineMat);

  // Occluder: same surface, filled with the ground colour, nudged back so lines win the depth fight.
  const occGeo = new THREE.SphereGeometry(1, 96, 64);
  const pos = occGeo.attributes.position as THREE.BufferAttribute;
  const tmp = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    deform(pos.getY(i), pos.getX(i), pos.getZ(i), tmp); // pole axis y -> x
    pos.setXYZ(i, tmp.x, tmp.y, tmp.z);
  }
  occGeo.computeVertexNormals();
  const occMat = new THREE.MeshBasicMaterial({ color: 0x040508, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1 });
  const occluder = new THREE.Mesh(occGeo, occMat);

  // The crease itself: one bright line along the groove floor, two dim ones on its shoulders.
  const creaseVerts: number[] = [];
  const creaseLine = (offset: number) => {
    let prev: THREE.Vector3 | null = null;
    for (let X = -1.3; X <= 1.3; X += 0.02) {
      const y = creaseY(X) + offset;
      const ux = X / 1.5, uy = y / 0.98;
      const zz = 1 - ux * ux - uy * uy;
      if (zz <= 0) { prev = null; continue; }
      const p = deform(ux, uy, Math.sqrt(zz)).clone();
      if (prev) creaseVerts.push(prev.x, prev.y, prev.z, p.x, p.y, p.z);
      prev = p;
    }
  };
  creaseLine(0);
  const creaseGeo = new THREE.BufferGeometry();
  creaseGeo.setAttribute('position', new THREE.Float32BufferAttribute(creaseVerts, 3));
  const creaseMat = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.95 });
  const crease = new THREE.LineSegments(creaseGeo, creaseMat);

  const bean = new THREE.Group();
  bean.add(occluder, lines, crease);

  // ---- measuring rings: quiet orbit lines around the bean ----
  const ringMat = new THREE.LineBasicMaterial({ color: 0xd8d8d8, transparent: true, opacity: 0.18 });
  const ringGeos: THREE.BufferGeometry[] = [];
  const makeRing = (rx: number, ry: number, tilt: number) => {
    const pts = new THREE.EllipseCurve(0, 0, rx, ry, 0, Math.PI * 2, false, 0).getPoints(160);
    const g = new THREE.BufferGeometry().setFromPoints(pts.map((p) => new THREE.Vector3(p.x, p.y, 0)));
    ringGeos.push(g);
    const l = new THREE.LineLoop(g, ringMat);
    l.rotation.x = tilt;
    return l;
  };
  const orbitA = makeRing(2.35, 2.35, 1.25);
  const orbitB = makeRing(2.0, 2.0, -0.6);
  const root = new THREE.Group();
  root.add(bean, orbitA, orbitB);
  root.rotation.z = 0.28;
  scene.add(root);

  // ---- sizing ----
  const resize = () => {
    const w = canvas.clientWidth || 1;
    const h = canvas.clientHeight || 1;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  };
  const ro = new ResizeObserver(() => {
    resize();
    if (reduced) renderer.render(scene, camera);
  });
  ro.observe(canvas);
  resize();

  // ---- state ----
  const mouse = { x: 0, y: 0, tx: 0, ty: 0 };
  let scrollP = 0; // 0 at top, 1 when the hero has scrolled out
  let visible = true;
  const t0 = performance.now();

  const frame = () => {
    if (!visible) return;
    const t = (performance.now() - t0) / 1000;
    mouse.x += (mouse.tx - mouse.x) * 0.06;
    mouse.y += (mouse.ty - mouse.y) * 0.06;
    // A slow turntable swing (not a full spin) so the crease side always stays in view.
    bean.rotation.y = -0.45 + Math.sin(t * 0.32) * 0.6 + mouse.x * 0.4 + scrollP * 2.4;
    bean.rotation.x = -0.5 + mouse.y * 0.22 + scrollP * 0.3;
    orbitA.rotation.z = t * 0.05;
    orbitB.rotation.z = -t * 0.04;
    const s = 1 - scrollP * 0.22;
    root.scale.setScalar(s);
    canvas.style.opacity = String(Math.max(0, 1 - scrollP * 1.25));
    renderer.render(scene, camera);
  };

  const onPointer = (e: PointerEvent) => {
    mouse.tx = (e.clientX / window.innerWidth - 0.5) * 2;
    mouse.ty = (e.clientY / window.innerHeight - 0.5) * 2;
  };
  const onScroll = () => {
    const r = hero.getBoundingClientRect();
    scrollP = THREE.MathUtils.clamp(-r.top / Math.max(1, r.height * 0.8), 0, 1);
  };

  let io: IntersectionObserver | undefined;
  if (reduced) {
    bean.rotation.set(-0.5, -0.45, 0);
    renderer.render(scene, camera);
  } else {
    gsap.ticker.add(frame);
    window.addEventListener('pointermove', onPointer, { passive: true });
    window.addEventListener('scroll', onScroll, { passive: true });
    io = new IntersectionObserver(([e]) => (visible = e.isIntersecting), { rootMargin: '10% 0px' });
    io.observe(hero);
  }

  document.documentElement.classList.add('has-gl');

  // Free GPU memory if the page is torn down (bfcache, navigation).
  const dispose = () => {
    gsap.ticker.remove(frame);
    window.removeEventListener('pointermove', onPointer);
    window.removeEventListener('scroll', onScroll);
    io?.disconnect();
    ro.disconnect();
    [lineGeo, occGeo, creaseGeo, ...ringGeos].forEach((g) => g.dispose());
    [lineMat, occMat, ringMat, creaseMat].forEach((m) => m.dispose());
    renderer.dispose();
  };
  window.addEventListener('pagehide', dispose, { once: true });
  return dispose;
}
